163.                             assert(self.bitmap@.set_bits.contains(i));
164.                         }
165.                     }
166.                 }
167.                 #[cfg(not(verus_keep_ghost))]
168.                 error!("{error:?}");
169.                 return Err(error);
170.             },
171.         };
172.         proof_decl! { let ghost idx = frame_number as int; }
173.         proof! {
174.             // `alloc` set a previously-clear, in-range bit; refcount is not yet mutated.
175.             assert(0 <= idx < pre_nb);
176.             assert(!pre_sb.contains(idx));
177.             assert(self.bitmap@.set_bits == pre_sb.insert(idx));
178.             assert(self.bitmap@.num_bits == pre_nb);
179.             assert(spec_refcount_seq(self) == pre_rc);
180.             // Representability: `num_bits` (= `pre_nb`) is unchanged, and `idx < pre_nb`, so the
