 //==================================================================================================
 // Imports
 //==================================================================================================

 use crate::hal::{
     mem::{
         FrameAddress,
         PageAligned,
         PhysicalAddress,
         TruncatedMemoryRegion,
     },
     platform::NFRAMES,
 };
 use ::arch::mem::{
