18.         FrameAllocView {
19.             allocated_frames: Set::new(|addr: int|
20.                 exists|i: int|
21.                     #[trigger] self.bitmap@.set_bits.contains(i)
22.                     && addr == frame_addr_of(i)
23.             ),
24.             free_frames: Set::new(|addr: int|
25.                 exists|i: int| {
